import{_ as e,o as r,c as d,a2 as a}from"./chunks/framework.BZO4qERu.js";const T=JSON.parse('{"title":"语音（TTS）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tts-providers/index.md","filePath":"zh/tts-providers/index.md","lastUpdated":1780941437000}'),o={name:"zh/tts-providers/index.md"};function i(l,t,n,s,h,p){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="语音-tts" tabindex="-1">语音（TTS） <a class="header-anchor" href="#语音-tts" aria-label="Permalink to &quot;语音（TTS）&quot;">​</a></h1><p>Memoh 支持把字变成声音。可以分三层想：</p><ul><li><strong>TTS Provider</strong>：一种服务类型（如 Edge TTS），在 TTS 页建<strong>具名实例</strong>。</li><li><strong>TTS Model</strong>：某实例下的具体声音/模型，可配音色、格式、变速、音高。</li><li><strong>机器人绑定</strong>：在机器人 <strong>General</strong> 里选 TTS Model，之后对话里可朗读。</li></ul><hr><h2 id="一般步骤" tabindex="-1">一般步骤 <a class="header-anchor" href="#一般步骤" aria-label="Permalink to &quot;一般步骤&quot;">​</a></h2><ol><li>侧栏 <strong>TTS Providers</strong>。</li><li><strong>Add</strong>，选类型（如 <code>edge</code>）。</li><li><strong>Create</strong>（常会自动导入默认模型）。</li><li>点进模型，调音色、格式等。</li><li>用页面试听。</li><li>机器人 <strong>General</strong> 里选这个 TTS Model 并保存。</li></ol><hr><h2 id="可用语音合成提供方" tabindex="-1">可用语音合成提供方 <a class="header-anchor" href="#可用语音合成提供方" aria-label="Permalink to &quot;可用语音合成提供方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>提供方</th><th>说明</th></tr></thead><tbody><tr><td><a href="/zh/tts-providers/edge.html">Edge TTS</a></td><td>走 Edge 公开朗读接口，无 key，多语音</td></tr><tr><td>OpenAI 兼容语音合成</td><td>使用 OpenAI 兼容的语音合成 API，需要匹配 provider 模板和凭据。</td></tr><tr><td>OpenRouter Speech</td><td>使用 OpenRouter 可用的语音合成路线，具体取决于账号能力。</td></tr><tr><td>ElevenLabs Speech</td><td>使用 ElevenLabs 语音合成模型和音色。</td></tr><tr><td>Deepgram Speech</td><td>使用 Deepgram 语音合成模型。</td></tr><tr><td>MiniMax Speech</td><td>使用 MiniMax 语音合成模型。</td></tr><tr><td>火山引擎语音合成</td><td>使用火山引擎语音合成模型。</td></tr><tr><td>阿里云语音合成</td><td>使用阿里云语音合成模型。</td></tr><tr><td>Microsoft Speech</td><td>使用 Microsoft 语音合成模型。</td></tr></tbody></table><p>具体模型、音色、格式和语言取决于你配置的 provider 模板与上游账号。</p><p>语音转写与 TTS 分开管理。Memoh 也支持 OpenAI 兼容、OpenRouter、ElevenLabs、Deepgram、Google 等语音转写 provider 类别。</p><hr><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>配无 key 的 Edge 选项：<a href="/zh/tts-providers/edge.html">Edge TTS</a></li><li>了解音频 provider client type 与模型关系：<a href="/zh/getting-started/provider-and-model.html">供应商与模型</a></li></ul>',14)])])}const c=e(o,[["render",i]]);export{T as __pageData,c as default};
